"""Read-only run identity and selected-run evidence guards."""

from __future__ import annotations

import hashlib
import json
import os
import stat
from collections.abc import Iterator
from contextlib import ExitStack, contextmanager
from dataclasses import dataclass
from pathlib import Path
from typing import Literal

from ovcaq.paths import RuntimePaths
from ovcaq.runtime._session_io import _encode_record, _private_directory, _publish
from ovcaq.runtime.registry import (
    FleetRun,
    ProcessIdentity,
    observe_unowned_run,
    process_matches,
    run_lock_held,
)
from ovcaq.state.schema import MAX_STATE_BYTES, State, decode_json
from ovcaq.state.store import StateError, StateStore


@dataclass(frozen=True)
class RunObservation:
    status: Literal["idle", "active", "inconsistent"]
    detail: str = "available"
    active_session_id: str | None = None
    run_id: str | None = None
    process: ProcessIdentity | None = None


@dataclass
class SelectedRunObservation:
    state: State | None
    observation: RunObservation
    ended: bool
    gaps: tuple[str, ...] = ()


def _state_digest(state: State) -> str:
    payload = json.dumps(state, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def publish_terminal_evidence(
    paths: RuntimePaths,
    *,
    run_id: str | None = None,
    process: ProcessIdentity | None = None,
    state: State | None = None,
) -> None:
    """Invalidate on acquisition; attest the owner's final state before cleanup."""
    _publish(
        paths.runtime_root / "run-terminal.json",
        _encode_record(
            {
                "schema_version": 1,
                "run_id": run_id,
                "pid": process.pid if process else None,
                "process_start": process.started if process else None,
                "state_digest": _state_digest(state) if state is not None else None,
            }
        ),
        identities=paths._identities,
    )


def _verify_terminal_state(
    paths: RuntimePaths, selected: FleetRun, state: State
) -> None:
    with ExitStack() as stack:
        directory = _private_directory(
            paths.runtime_root, stack, identities=paths._identities, create=False
        )
        descriptor = os.open(
            "run-terminal.json",
            os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,
            dir_fd=directory,
        )
        with os.fdopen(descriptor, "rb") as stream:
            if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
                raise ValueError("final evidence must be a regular file")
            payload = stream.read(MAX_STATE_BYTES + 1)
        if len(payload) > MAX_STATE_BYTES:
            raise ValueError("final evidence exceeds size limit")
    record = decode_json(payload.decode("utf-8"), source="run-terminal.json")
    if record != {
        "schema_version": 1,
        "run_id": selected.run_id,
        "pid": selected.pid,
        "process_start": selected.process_start,
        "state_digest": _state_digest(state),
    }:
        raise ValueError("final state does not belong to the selected run")


def _selected_state(paths: RuntimePaths, selected: FleetRun) -> SelectedRunObservation:
    identity = ProcessIdentity(selected.pid, selected.process_start)
    # Once death is observed, sample metadata after cleanup rather than combining
    # an earlier active observation with the owner's later absence.
    ended = not process_matches(identity)
    observation = observe_run(paths)
    if not ended and observation.status != "active":
        # Cleanup may have overtaken the initial identity read. Confirm death
        # once, then require fresh metadata and the normal terminal attestation.
        ended = not process_matches(identity)
        if ended:
            observation = observe_run(paths)
    try:
        if selected.root != paths.project_root:
            raise ValueError("selected run root changed")
        if ended:
            with observe_unowned_run(paths.run_lock):
                if observation.status != "idle":
                    raise ValueError("selected run was replaced or has stale metadata")
                state = StateStore(paths.state_file).read()
                _verify_terminal_state(paths, selected, state)
        else:
            if (observation.run_id, observation.process) != (selected.run_id, identity):
                raise ValueError("selected run identity is unavailable")
            state = StateStore(paths.state_file).read()
            if observe_run(paths) != observation:
                raise ValueError("selected run changed during state observation")
        return SelectedRunObservation(state, observation, ended)
    except (OSError, ValueError, StateError) as error:
        return SelectedRunObservation(
            None, observation, ended, (f"selected state unavailable: {error}",)
        )


@contextmanager
def observe_selected_run(
    paths: RuntimePaths, selected: FleetRun, *, batch_id: str | None
) -> Iterator[SelectedRunObservation]:
    """Invalidate the observation on exit if ownership changed during evidence reads."""
    result = _selected_state(paths, selected)
    yield result
    if result.state is None:
        return
    after = _selected_state(paths, selected)
    if (
        after.state is None
        or (result.ended and after.state != result.state)
        or after.ended != result.ended
        or after.observation != result.observation
        or (batch_id is not None and result.state["batch"]["id"] != batch_id)
    ):
        # An attested live-to-terminal transition crossed this evidence read.
        # Leave this invalidated frame nonterminal; the next poll must collect
        # its own coherent final evidence before the viewer stops observing.
        terminal_transition = (
            not result.ended
            and after.ended
            and after.state is not None
            and (batch_id is None or after.state["batch"]["id"] == batch_id)
        )
        result.state = None
        result.ended = after.ended and not terminal_transition
        result.gaps = after.gaps or ("selected state changed during evidence reads",)


def observe_run(paths: RuntimePaths) -> RunObservation:
    """Observe authority and validated process identity once without taking locks."""
    from ovcaq.runtime.session import parse_session_metadata

    try:
        directory = os.open(
            paths.runtime_root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
        )
    except FileNotFoundError:
        return RunObservation("idle")
    except OSError as error:
        return RunObservation("inconsistent", str(error))
    try:
        locked = run_lock_held(Path("run.lock"), directory=directory)
        try:
            record_fd = os.open(
                "run.json",
                os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,
                dir_fd=directory,
            )
        except FileNotFoundError:
            if locked:
                return RunObservation("inconsistent", "held run lock has no metadata")
            return RunObservation("idle")
        with os.fdopen(record_fd, "rb") as stream:
            if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
                raise ValueError("run metadata must be regular")
            payload = stream.read(MAX_STATE_BYTES + 1)
        if len(payload) > MAX_STATE_BYTES:
            raise ValueError("run metadata exceeds size limit")
        metadata = parse_session_metadata(
            decode_json(payload.decode("utf-8"), source="run.json")
        )
        if not locked:
            return RunObservation("inconsistent", "run metadata has no held run lock")
        if not process_matches(ProcessIdentity(metadata.pid, metadata.process_start)):
            return RunObservation("inconsistent", "run process identity is stale")
        return RunObservation(
            "active",
            active_session_id=metadata.session_id,
            run_id=metadata.run_id,
            process=ProcessIdentity(metadata.pid, metadata.process_start),
        )
    except (OSError, ValueError, TypeError) as error:
        return RunObservation("inconsistent", str(error))
    finally:
        os.close(directory)

    if len(unique) <= MAX_GAPS:
        return unique
    return (*unique[: MAX_GAPS - 1], GAPS_OMITTED)


class ProjectObserver:
    """Poll one selected run's shared observations into a ProjectView."""

    def __init__(self, run: FleetRun, settings: RuntimeSettings) -> None:
        self._run = run
        self._paths = settings.paths
        self._batch_id: str | None = None
        self._view: ProjectView | None = None
        self._ended = False
        self._follower = JsonlFollower(
            settings.paths.events,
            # The tail and event modules declare equal but distinct JSON aliases.
            cast(
                Callable[[Mapping[str, object]], Observation], observation_from_record
            ),
        )
        self._session_id: str | None = None
        self._gaps: tuple[str, ...] = ()
        self._clear()

    def _clear(self) -> None:
        self._lanes: dict[str, ActivityLane] = {}
        self._activity: dict[tuple[str, str], ActivityItem] = {}
        self._activity_sequence = 0
        self._usage: dict[str | None, Mapping[str, object]] = {}
        self._provider = "unknown"
        self._normalized = False
        self._raw = False

    def close(self) -> None:
        self._follower.close()

    def poll(self) -> ProjectView:
        if self._view is not None and self._view.ended:
            return self._view
        gaps: list[str] = []
        state, observation, emergency, metrics, raw_evidence = self._observe(gaps)
        rows = metrics.rows if metrics is not None else ()
        for row in rows:
            if row.finished_at is not None:
                self._usage.pop(row.session_id, None)
        live_usage = list(self._usage.values())
        usage = _usage_view(
            [*(row.usage for row in rows if row.usage is not None), *live_usage],
            any(row.usage is None for row in rows),
            (metrics is None or metrics.complete) and not live_usage,
        )
        status = _status(
            state,
            observation,
            emergency if _emergency_current(emergency, self._run) else None,
            rows,
            ended=self._ended,
        )
        if state is None and self._view is not None:
            self._view = replace(
                self._view,
                status="unknown",
                ended=self._ended,
                duration_seconds=None if self._ended else self._view.duration_seconds,
                telemetry="partial",
                gaps=_bounded_gaps([*self._view.gaps, *gaps]),
            )
        else:
            self._view = self._project(
                state,
                status,
                usage,
                raw_evidence,
                rows,
                gaps,
            )
        if self._view.ended:
            self.close()
        return self._view

    def _duration(
        self, state: State | None, rows: tuple[SessionMetric, ...]
    ) -> float | None:
        try:
            started = datetime.fromisoformat(self._run.started_at)
            end = datetime.now(UTC)
            if self._ended:
                completed = state["batch"]["completed_at"] if state else None
                end = (
                    datetime.fromisoformat(completed)
                    if completed is not None
                    else max(
                        datetime.fromisoformat(row.finished_at)
                        for row in rows
                        if row.run_id == self._run.run_id
                        and row.finished_at is not None
                    )
                )
            elapsed = (end - started).total_seconds()
            return elapsed if elapsed >= 0 else None
        except (ValueError, TypeError):
            return None

    def _project(
        self,
        state: State | None,
        status: RunStatus,
        usage: UsageView | None,
        raw_evidence: bool,
        rows: tuple[SessionMetric, ...],
        gaps: list[str],
    ) -> ProjectView:
        bounded = _bounded_gaps(gaps)
        duration_seconds = self._duration(state, rows)
        work = state["work"] if state is not None else None
        notice = state["control"]["attention"] if state is not None else None
        return ProjectView(
            run=self._run,
            status="stopped" if self._ended and status == "stopping" else status,
            phase=work["phase"] if work else None,
            next_phase=work["next_phase"] if work else None,
            prd=display_text(work["prd"]) if work and work["prd"] else None,
            revision=state["revision"] if state is not None else None,
            tasks_completed=work["tasks_completed"] if work else None,
            tasks_total=work["tasks_total"] if work else None,
            review_cycle=state["review"]["cycle"] if state is not None else None,
            provider=self._provider,
            duration_seconds=duration_seconds,
            usage=usage,
            lanes=tuple(self._lanes.values()),
            capabilities=(
                _capabilities(self._run, state, self._paths.sessions) if state else ()
            ),
            attention=None
            if notice is None
            else Notice(
                site=display_text(notice["site"]),
                detail=display_text(notice["detail"]),
                created_at=notice["created_at"],
            ),
            telemetry=self._telemetry(bounded, raw_evidence, bool(rows)),
            gaps=bounded,
            ended=self._ended,
            activity=tuple(self._activity.values()),
        )

    def _telemetry(
        self, gaps: tuple[str, ...], raw_evidence: bool, has_rows: bool
    ) -> TelemetryLevel:
        if gaps:
            return "partial"
        if not self._normalized and (self._raw or raw_evidence):
            return "raw-only"
        if not self._normalized and not has_rows:
            return "unavailable"
        return "complete"

    def _observe(
        self, gaps: list[str]
    ) -> tuple[
        State | None,
        RunObservation | None,
        EmergencyFailureObservation | None,
        MetricsSnapshot | None,
        bool,
    ]:
        try:
            with observe_selected_run(
                self._paths, self._run, batch_id=self._batch_id
            ) as selected:
                evidence = self._evidence(selected, gaps)
        except _OBSERVATION_ERRORS as error:
            selected = SelectedRunObservation(
                None,
                RunObservation("inconsistent"),
                self._ended,
                (f"selected run unavailable: {type(error).__name__}",),
            )
        if selected.state is None:
            # Preserve only this selection's live session across an invalidated
            # sample, so a later attested terminal frame can consume final events.
            if selected.ended or (
                selected.observation.run_id,
                selected.observation.process,
            ) != (
                self._run.run_id,
                ProcessIdentity(self._run.pid, self._run.process_start),
            ):
                self.close()
                self._clear()
                self._session_id, self._gaps = None, ()
            self._ended = selected.ended
            gaps.extend(selected.gaps)
            return None, selected.observation, None, None, False
        self._batch_id = selected.state["batch"]["id"]
        return evidence

    def _evidence(
        self, selected: SelectedRunObservation, gaps: list[str]
    ) -> tuple[
        State | None,
        RunObservation,
        EmergencyFailureObservation | None,
        MetricsSnapshot | None,
        bool,
    ]:
        state, observation = selected.state, selected.observation
        self._ended = selected.ended
        gaps.extend(selected.gaps)
        emergency = metrics = evidence = None
        if state is not None:
            emergency = _guard(
                gaps, "emergency marker", observe_emergency_failure, self._paths
            )
            metrics = _guard(
                gaps,
                "metrics",
                observe_metrics,
                self._paths,
                batch_id=state["batch"]["id"],
            )
            session_id = (
                self._session_id if self._ended else observation.active_session_id
            )
            if session_id is not None:
                evidence = _guard(
                    gaps,
                    "session evidence",
                    observe_session_evidence,
                    self._paths,
                    session_id,
                )
                self._apply(session_id, gaps)
        if emergency is not None and emergency.malformed:
            gaps.append("emergency failure marker is malformed")
        if metrics is not None:
            gaps.extend(
                metrics.gaps or (() if metrics.complete else ("metrics incomplete",))
            )
        raw_evidence = evidence is not None and evidence.raw_only
        return state, observation, emergency, metrics, raw_evidence

    def _apply(self, session_id: str, gaps: list[str]) -> None:
        if session_id != self._session_id:
            self.close()
            self._follower = JsonlFollower(
                self._paths.sessions / session_id / "normalized.jsonl",
                cast(
                    Callable[[Mapping[str, object]], Observation],
                    observation_from_record,
                ),
            )
            self._session_id, self._gaps = session_id, ()
            self._clear()
        batch = _guard(gaps, "events", self._follower.read)
        if batch is None:
            return
        if batch.reset:
            self._clear()
        persistent = list(self._gaps)
        persistent.extend(f"events {g.kind}: {g.detail}" for g in batch.gaps)
        if not batch.complete_history and not batch.backlog:
            persistent.append("event history incomplete")
        self._gaps = _bounded_gaps(persistent)
        gaps.extend(self._gaps)
        if batch.backlog:
            gaps.append("event backlog pending")
        for event in batch.records:
            if (event.run_id, event.session_id) != (self._run.run_id, session_id):
                continue
            self._provider = display_text(event.provider)
            if event.type is ObservationType.RAW_UNKNOWN:
                self._raw = True
                continue
            self._normalized = True
            if event.type is ObservationType.USAGE_UPDATED:
                usage = event.payload["usage"]
                assert isinstance(usage, Mapping)
                # Latest identity per session wins; re-insert to mark it newest.
                self._usage.pop(event.session_id, None)
                self._usage[event.session_id] = usage
                if len(self._usage) > MAX_USAGE_SESSIONS:
                    del self._usage[next(iter(self._usage))]
            elif event.type in _LANE_STATUS and event.lane_id is not None:
                self._observe_lane(event, event.lane_id, gaps)
            elif event.type in (
                ObservationType.TOOL_STARTED,
                ObservationType.TOOL_COMPLETED,
                ObservationType.TOOL_FAILED,
                ObservationType.ACTIVITY_MESSAGE,
            ):
                self._observe_activity(event)

    def _observe_activity(self, event: Observation) -> None:
        payload = event.payload
        if event.type is ObservationType.ACTIVITY_MESSAGE:
            message_id = payload.get("message_id")
            if isinstance(message_id, str) and message_id.strip():
                key = ("message", message_id)
            else:
                self._activity_sequence += 1
                key = ("anonymous", str(self._activity_sequence))
            label = display_text(str(payload.get("kind", "message")))
            detail = payload.get("text")
            if detail is None:
                detail = payload.get("detail")
            if label == "plan":
                items = payload.get("items", ())
                if isinstance(items, (tuple, list)):
                    detail = " / ".join(
                        ("done: " if item.get("completed") is True else "pending: ")
                        + display_text(str(item.get("text", "")))
                        for item in items[:MAX_ACTIVITY]
                        if isinstance(item, Mapping)
                    )
            status = None
        else:
            key = ("tool", display_text(str(payload.get("tool_id", ""))))
            previous = self._activity.get(key)
            label = display_text(
                str(payload.get("name", previous.label if previous else "tool"))
            )
            detail = payload.get("detail")
            status = event.type.value.removeprefix("tool.")
        self._activity.pop(key, None)
        self._activity[key] = ActivityItem(
            label, status, None if detail is None else display_text(str(detail))
        )
        if len(self._activity) > MAX_ACTIVITY:
            del self._activity[next(iter(self._activity))]

    def _observe_lane(self, event: Observation, lane_id: str, gaps: list[str]) -> None:
        previous = self._lanes.get(lane_id)
        label = _payload_text(event, "label", gaps)
        if label is None:
            label = _payload_text(event, "description", gaps)
        detail = _payload_text(event, "detail", gaps)
        status = _LANE_STATUS[event.type]
        if event.type is not ObservationType.LANE_STARTED and (
